def solve(coins, amount):
    """Return the minimum number of coins needed to make up the given amount using unlimited coins of each denomination.
    If it's not possible, return -1.
    Uses classic bottom‑up dynamic programming in O(amount * len(coins)) time.
    """
    if amount < 0:
        return -1
    # dp[i] = minimum coins to make amount i
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                # if we can use coin c, consider using it
                prev = dp[i - c]
                if prev + 1 < dp[i]:
                    dp[i] = prev + 1
    return dp[amount] if dp[amount] != float('inf') else -1

