    and skips malformed entries.
    """
    # Normalise intervals
    intervals = []
    for m in meetings:
        try:
            s, e = m[0], m[1]
        except Exception:
            continue
        if not isinstance(s, (int, float)) or not isinstance(e, (int, float)):
            continue
        if s > e:
            s, e = e, s
        intervals.append((s, e))
    if not intervals:
        return 0
    # Greedy by earliest finish time
    intervals.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for s, e in intervals:
        if s >= current_end:
            count += 1
            current_end = e
    return count

