def solve(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting (binary search) in O(n log n).
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # find insertion point in tails (first >= x)
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

