{"task_id": "T21", "code": "def solve(weights, values, capacity):
    """Return the maximum total value for a 0/1 knapsack.
    Uses O(capacity) DP and works for zero‑weight items as well.
    """
    if capacity <= 0 or not weights:
        return 0
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        # Skip items that cannot fit at all (including negative weight)
        if w > capacity:
            continue
        # Iterate backwards to ensure each item is used at most once
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]
