def solve(matrix):
    n = len(matrix)
    if n == 0:
        return 1
    # Ensure square matrix
    if any(len(row) != n for row in matrix):
        return 1
    # Make a copy as Fractions
    A = [[Fraction(x) for x in row] for row in matrix]
    det_sign = 1
    for i in range(n):
        # Find pivot
        pivot = None
        for r in range(i, n):
            if A[r][i] != 0:
                pivot = r
                break
        if pivot is None:
            return 0
        if pivot != i:
            A[i], A[pivot] = A[pivot], A[i]
            det_sign *= -1
        # Eliminate below
        for r in range(i+1, n):
            factor = A[r][i] / A[i][i]
            for c in range(i, n):
                A[r][c] -= factor * A[i][c]
    det = det_sign
    for i in range(n):
        det *= A[i][i]
    # det should be integer
