def solve(a, x):
    """Return the leftmost insertion index for x in a sorted sequence a.
    Handles a being None or empty by treating it as an empty list.
    """
    # Treat None as empty list
    if not a:
        return 0
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        # Use < for leftmost (first position where a[mid] >= x)
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

