    """0/1 knapsack: maximize total value without exceeding capacity.
    Handles zero-weight items correctly.
    """
    # Sum values of zero-weight items (they can always be taken)
    zero_val = 0
    filtered = []
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                zero_val += v
        else:
            filtered.append((w, v))
    if capacity <= 0 or not filtered:
        return zero_val
    dp = [0] * (capacity + 1)
    for w, v in filtered:
        for c in range(capacity, w - 1, -1):
