            if y < 0 or y >= len(grid[x]):
                continue
            if visited[x][y] or grid[x][y] == 0:
                continue
            visited[x][y] = True
            # neighbours: up, down, left, right
            stack.append((x-1, y))
            stack.append((x+1, y))
            stack.append((x, y-1))
            stack.append((x, y+1))
    count = 0
