def solve(coins, amount):
    """Return minimum number of coins needed to make *amount* using unlimited *coins*.
    If impossible, return -1.
    Uses DP with O(amount * len(coins)) time.
    """
    if amount < 0:
        return -1
    # DP array where dp[i] = min coins for amount i
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                dp[i] = min(dp[i], dp[i - c] + 1)
    return dp[amount] if dp[amount] != INF else -1

