def solve(n, edges):
    from heapq import heappush, heappop
    # Build adjacency list and indegree counts
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        adj[a].append(b)
        indeg[b] += 1
    # Use a min-heap to always pick the smallest available node
    heap = []
    for i in range(n):
        if indeg[i] == 0:
            heappush(heap, i)
    order = []
    while heap:
        u = heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heappush(heap, v)
    # If we couldn't include all nodes, there is a cycle
    if len(order) != n:
        return []
    return order

def solve(coins, amount):
    """Return the minimum number of coins needed to make *amount* with unlimited supply.
    Coins with non‑positive value are ignored because they cannot contribute positively.
    If *amount* is negative, or it's impossible to reach, return -1.
    """
    if amount < 0:
        return -1
    # Filter out non‑positive coin values
    positive_coins = [c for c in coins if c > 0]
    if amount == 0:
        return 0
    if not positive_coins:
        return -1
    # DP array: dp[i] = min coins to make i, INF means unreachable
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        best = INF
        for c in positive_coins:
            if c <= i:
                cand = dp[i - c] + 1
                if cand < best:
                    best = cand
        dp[i] = best
    return dp[amount] if dp[amount] != INF else -1

