def solve(a, x):
    """Return the leftmost index at which x can be inserted into sorted list a.
    Uses binary search for O(log n) time.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

