    n = len(s)
    if n == 0:
        return 0
    last_idx = {}
    max_len = 0
    start = 0  # start index of current window
    for i, ch in enumerate(s):
        if ch in last_idx and last_idx[ch] >= start:
            # duplicate within current window, move start
            start = last_idx[ch] + 1
        last_idx[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

